SELECT s.sell_products_no AS sellProductsNo, p.products_nm AS productName, s.margin_ratio_no AS marginRatioNo, m.model_nm AS modelName, s.ent_ceo_no AS entCeoNo, s.ent_emp_id AS entEmpId, s.products_no AS productsNo, s.lump_sum_pay_price AS lumpSumPayPrice, s.period AS period, s.calculate_price AS calculatePrice, s.final_price AS finalPrice, DATE_FORMAT(s.register_date, '%Y-%m-%d %H:%i:%s') AS registerDate, DATE_FORMAT(s.revision_date, '%Y-%m-%d %H:%i:%s') AS revisionDate, s.use_status AS useStatus, IFNULL(f.file_path, '/manage/assets/imgs/theme/upload.svg') AS productImage FROM sell_products s LEFT JOIN products p ON s.products_no = p.products_no LEFT JOIN model m ON p.model_no = m.model_no LEFT JOIN files f ON f.ref_id = p.model_no AND f.file_type = 'mainImage' WHERE 1=1
AND p.products_nm LIKE CONCAT('%', #{searchValue}, '%')
AND m.model_nm LIKE CONCAT('%', #{searchValue}, '%')
AND p.category_no = #{categoryNo}
AND s.use_status = #{status}
ORDER BY s.register_date DESC

SELECT COUNT(*)
FROM sell_products
WHERE ent_ceo_no = #{entCeoNo}
  AND products_no = #{productsNo}
  AND period = #{period}

SELECT s.sell_products_no AS sellProductsNo, p.products_nm AS productName, s.margin_ratio_no AS marginRatioNo, m.model_nm AS modelName, s.ent_ceo_no AS entCeoNo, s.ent_emp_id AS entEmpId, s.products_no AS productsNo, s.lump_sum_pay_price AS lumpSumPayPrice, s.period AS period, s.calculate_price AS calculatePrice, s.final_price AS finalPrice, DATE_FORMAT(s.register_date, '%Y-%m-%d %H:%i:%s') AS registerDate, DATE_FORMAT(s.revision_date, '%Y-%m-%d %H:%i:%s') AS revisionDate, s.use_status AS useStatus, IFNULL(f.file_path, '/manage/assets/imgs/theme/upload.svg') AS mainImageData FROM sell_products s LEFT JOIN products p ON s.products_no = p.products_no LEFT JOIN model m ON p.model_no = m.model_no LEFT JOIN brand b ON m.brand_no = b.brand_no LEFT JOIN files f ON f.ref_id = p.model_no AND f.file_type = 'mainImage'
AND p.products_nm LIKE CONCAT('%', #{searchValue}, '%')
AND b.brand_nm LIKE CONCAT('%', #{searchValue}, '%')
AND p.product_category_no = #{categoryNo}
AND s.use_status = #{status}
ORDER BY s.register_date DESC

